  '\\nMapping for “%s”\\n' => 'Zuordnung für „%s“',
  '\\nThis form charges in%1$sbut the donation type is in%2$s: its payments are stopped until both use the same currency.\\n' => 'Dieses Formular berechnet in%1$s, aber der Spendentyp ist in%2$s: Die Zahlungen werden gestoppt, bis beide dieselbe Währung verwenden.',
  '\\nThis form has no priced choices to map.\\n' => 'Dieses Formular verfügt über keine zuzuordnenden Preisoptionen.',
  '\\nForm choice\\n' => 'Formularauswahl',
  '\\nUnits\\n' => 'Einheiten',
  '\\nform price:%s\\n' => 'Preis bilden:%s',
