  '\\nFree amount field\\n' => 'Freier Betragsfeld',
  '\\nOn behalf of (names field)\\n' => 'Im Namen von (Namensfeld)',
  '\\nOne name per line. Units without a name are given on behalf of the donor.\\n' => 'Ein Name pro Zeile. Einheiten ohne Namen werden im Namen des Spenders abgegeben.',
  '\\nProxy consent field\\n' => 'Proxy-Zustimmungsfeld',
  '\\nMonthly, weekly or yearly gifts charged automatically by the payment provider.\\n' => 'Monatliche, wöchentliche oder jährliche Geschenke, die automatisch vom Zahlungsanbieter abgerechnet werden.',
  '\\nName, e-mail, phone, reference...\\n' => 'Name, E-Mail, Telefon, Referenz...',
  '\\nNo recurring donations yet\\n' => 'Noch keine wiederkehrenden Spenden',
  '\\nA recurring donation is created when a payment form is set to charge every day, week, month or year.\\n' => 'Eine wiederkehrende Spende wird erstellt, wenn ein Zahlungsformular so eingestellt ist, dass es jeden Tag, jede Woche, jeden Monat oder jedes Jahr belastet.',
  '[[\'%srecurring donation\', \'en\']]' . chr(0) . '[[\'%srecurring donations\', \'en\']]' => '%swiederkehrende Spende' . chr(0) . '%swiederkehrende Spenden',
  '\\nInterval\\n' => 'Intervall',
