  '\\nNext charge\\n' => 'Nächste Ladung',
  '\\nAttempt%1$sof%2$sfailed:%3$s\\n' => 'Versuch%1$svon%2$sfehlgeschlagen:%3$s',
  '\\ncanceled%s\\n' => 'abgebrochen%s',
  '\\nCancel this recurring donation at the payment provider? No further charges will be made.\\n' => 'Diese wiederkehrende Spende beim Zahlungsanbieter stornieren? Es werden keine weiteren Gebühren erhoben.',
  'WooCommerce' => 'WooCommerce',
  '\\nCard payments: the official iyzico plugin is enabled.\\n' => 'Kartenzahlungen: Das offizielle iyzico-Plugin ist aktiviert.',
  '\\nCard payments: Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => 'Kartenzahlungen: Flux Donate iyzico (das offizielle iyzico-Plugin ist nicht aktiviert).',
  '\\nCard payments:%s.\\n' => 'Kartenzahlungen:%s.',
  '\\nNo card method is enabled (WooCommerce › Settings › Payments).\\n' => 'Es ist keine Kartenmethode aktiviert (WooCommerce › Einstellungen › Zahlungen).',
  '\\nMonthly donations: Flux Donate iyzico is ready.\\n' => 'Monatliche Spenden: Flux Donate iyzico ist bereit.',
  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" and enter iyzico keys.\\n' => 'Monatliche Spenden sind deaktiviert: Aktivieren Sie „Card (iyzico) – Flux Donate“ und geben Sie iyzico-Schlüssel ein.',
  '\\nBank transfer (donations) is enabled.\', \'en\']]' => 'Banküberweisung (Spenden) ist aktiviert.',
  '\\nBank transfer (donations) is disabled.\\n' => 'Banküberweisung (Spenden) ist deaktiviert.',
  '\\nFlux Certificates is connected.\\n' => 'Flux Certificates ist verbunden.',
  '\\nFlux Certificates is active but has no active template.\\n' => 'Flux Certificates ist aktiv, hat aber keine aktive Vorlage.',
  '\\nFlux Certificates is not active: no certificate is made after payment.\\n' => 'Flux-Zertifikate sind nicht aktiv: Nach der Zahlung wird kein Zertifikat erstellt.',
  '\\nDonation page:\\n' => 'Spendenseite:',
  '\\nThe donation options are not on a page yet.\\n' => 'Die Spendenoptionen sind noch nicht auf einer Seite.',
  '\\nWooCommerce is not active. Donations are paid through WooCommerce from version 2.0: install and activate WooCommerce.\\n' => 'WooCommerce ist nicht aktiv. Spenden werden über WooCommerce ab Version 2.0 bezahlt: WooCommerce installieren und aktivieren.',
  '\\nSapling packages, prices and badges are edited on the donation type (Donations › Donation types). Which types give a certificate is set there too.\\n' => 'Setzlingspakete, Preise und Abzeichen werden auf der Spendenart bearbeitet (Spenden › Spendenarten). Dort wird auch eingestellt, welche Typen ein Zertifikat ergeben.',
  'Template' => 'Vorlage',
  '[[\'Automatic ("Fidan Bağış Sertifikası")\\n' => 'Automatisch ("Fidan Bağış Sertifikası")',
  'Event' => 'Veranstaltung',
  '\\nWhen chosen, online donation certificates count for this open event.\\n' => 'Wenn ausgewählt, zählen Online-Spendenzertifikate für diese offene Veranstaltung.',
  '\\nSend by\\n' => 'Senden per',
  '\\nWhen the payment is confirmed the certificate link goes out on these channels. With a WhatsApp route no SMS is sent.\\n' => 'Wenn die Zahlung bestätigt ist, wird der Zertifikatslink auf diesen Kanälen verschickt. Bei einer WhatsApp-Route wird keine SMS versendet.',
  '\\n"Online + printed certificate"\\n' => '"Online + gedrucktes Zertifikat"',
  '\\nShown as "Coming soon" (cannot be chosen)\\n' => 'Wird als „In Kürze verfügbar“ angezeigt (kann nicht ausgewählt werden)',
  '\\nCan be chosen\\n' => 'Kann ausgewählt werden',
  'Hidden' => 'Versteckt',
  '\\nPrinted certificate fee (per line)\\n' => 'Gebühr für gedrucktes Zertifikat (pro Zeile)',
  '\\n0 = free. Orders with a printed certificate stay "Processing"; set them to "Completed" when sent.\\n' => '0 = kostenlos. Bestellungen mit ausgedrucktem Zertifikat bleiben „in Bearbeitung“; Setzen Sie sie beim Senden auf „Abgeschlossen“.',
  '\\nComplete paid orders with an online certificate automatically\\n' => 'Bezahlte Bestellungen automatisch mit einem Online-Zertifikat abschließen',
  '\\nIBAN, recipient and reference code: WooCommerce › Settings › Payments › Bank transfer (donations). The transfer details and the receipt link are added to WooCommerce\\\'s "on hold" e-mail.\\n' => 'IBAN, Empfänger- und Referenzcode: WooCommerce › Einstellungen › Zahlungen › Banküberweisung (Spenden). Die Überweisungsdetails und der Beleglink werden zur Warteschleifen-E-Mail von WooCommerce hinzugefügt.',
  '\\nShort notification\\n' => 'Kurze Benachrichtigung',
  '\\nA short message to the donor\\\'s phone when a transfer is registered (through Flux Mail, or Flux Certificates\\\'s providers). With both ticked, SMS only goes out when there is no WhatsApp route.\\n' => 'Eine kurze Nachricht an das Telefon des Spenders, wenn eine Überweisung registriert wird (über Flux Mail oder die Anbieter von Flux Certificates). Wenn beides aktiviert ist, werden SMS nur dann verschickt, wenn keine WhatsApp-Route vorhanden ist.',
  '\\nWhatsApp text\\n' => 'WhatsApp-Text',
  '\\nPlaceholders:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}\\n' => 'Platzhalter:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}',
  '\\nSMS text\\n' => 'SMS-Text',
  '\\nLargest receipt file (MB)\\n' => 'Größte Belegdatei (MB)',
  '\\nTell this address when a receipt is uploaded\\n' => 'Geben Sie diese Adresse an, wenn eine Quittung hochgeladen wird',
  'Cart and checkout' => 'Warenkorb und Kasse',
  '\\nAfter "Donate"\\n' => 'Nach „Spenden“',
  '\\nGo straight to the checkout\\n' => 'Gehen Sie direkt zur Kasse',
  '\\nGo to the cart\\n' => 'Gehe zum Warenkorb',
  '\\nStay on the page\\n' => 'Bleiben Sie auf der Seite',
  '\\nCurrencies donors can choose\\n' => 'Währungen, die Spender wählen können',
  '\\n(store currency)\\n' => '(Währung speichern)',
  '\\nWith more than one, donors pick the currency (shortcode [flx_bagis_para_birimi] or the theme). There are no exchange rates: set each option\\\'s price per currency on the donation type; options without a price in a currency are not offered in it. Check that your payment methods take these currencies.\', \'en\']]' => 'Bei mehr als einer wählen die Spender die Währung aus (Shortcode [flx_bagis_para_birimi] oder das Thema). Es gibt keine Wechselkurse: Legen Sie den Preis jeder Option pro Währung für die Spendenart fest; Optionen ohne Preis in einer Währung werden darin nicht angeboten. Überprüfen Sie, ob Ihre Zahlungsmethoden diese Währungen akzeptieren.',
  '\\nDo not ask for an address at the checkout when the cart holds only donations\\n' => 'Fragen Sie an der Kasse nicht nach einer Adresse, wenn sich im Warenkorb nur Spenden befinden',
  '\\nSupport WhatsApp number\\n' => 'Unterstützen Sie die WhatsApp-Nummer',
  '\\nShown at the checkout and with the bank transfer details as "Any trouble? Write to us on WhatsApp". Leave empty to hide.\\n' => 'Wird an der Kasse angezeigt und mit den Banküberweisungsdaten als „Haben Sie Probleme? Schreiben Sie uns über WhatsApp“. Zum Verstecken leer lassen.',
  '\\n— Choose —\\n' => ' – Wählen Sie –',
  '\\n"Donate" links and the hidden product pages go here.\\n' => 'Hier gelangen die „Spenden“-Links und die ausgeblendeten Produktseiten.',
  '\\nCard payment method\\n' => 'Kartenzahlungsmethode',
  '\\nAutomatic: another virtual POS if one is enabled (e.g. EsnekPOS), otherwise iyzico\\n' => 'Automatisch: ein anderer virtueller POS, falls einer aktiviert ist (z. B. EsnekPOS), andernfalls iyzico',
  '\\niyzico\\n' => 'iyzico',
  '\\nShow every enabled card method\', \'en\']]' => 'Jede aktivierte Kartenmethode anzeigen',
  '\\nDonors see one card method; now:%s. Monthly donations always use Flux Donate iyzico (it stores the card). Bank transfer is always shown.\\n' => 'Spender sehen eine Kartenmethode; jetzt:%s. Für monatliche Spenden verwenden Sie immer Flux Donate iyzico (es speichert die Karte). Banküberweisung wird immer angezeigt.',
  '\\nall\\n' => 'alle',
  '\\nShow other payment plugins on the checkout block\\n' => 'Andere Zahlungs-Plugins im Checkout-Block anzeigen',
  '\\nVirtual POS plugins that take the card on their own page but have no checkout block support (for example EsnekPOS) are added to the Checkout block. Plugins with their own card fields need the classic checkout.\\n' => 'Virtuelle POS-Plugins, die die Karte auf ihrer eigenen Seite aufnehmen, aber keine Checkout-Block-Unterstützung haben (z. B. EsnekPOS), werden dem Checkout-Block hinzugefügt. Plugins mit eigenen Kartenfeldern benötigen den klassischen Checkout.',
  '\\nFlux Forms payment forms continue on the WooCommerce checkout\\n' => 'Flux Forms-Zahlungsformulare werden im WooCommerce-Checkout fortgesetzt',
  '\\nThe donor picks card or bank transfer there; the form entry, the certificate automation and the donation record are completed when the order is paid.\\n' => 'Der Spender wählt dort Karte oder Banküberweisung aus; Die Formulareingabe, die Zertifikatsautomatisierung und die Spendenaufzeichnung sind mit der Bezahlung der Bestellung abgeschlossen.',
  '\\nCard payment screen\\n' => 'Bildschirm für Kartenzahlung',
  '\\nOur own card fields on the checkout (3D Secure, installments, saved cards)\\n' => 'Unsere eigenen Kartenfelder an der Kasse (3D Secure, Raten, gespeicherte Karten)',
  '\\niyzico payment page (as before)\\n' => 'iyzico-Zahlungsseite (wie zuvor)',
  '\\nOfficial iyzico plugin for one-time donations\\n' => 'Offizielles iyzico-Plugin für einmalige Spenden',
