  '\\nCard (iyzico), monthly\\n' => 'Karte (iyzico), monatlich',
  '\\nMonthly renewal of recurring donation #%1$d(first order #%2$s).\\n' => 'Monatliche Erneuerung der wiederkehrenden Spende #%1$d(Erstbestellung #%2$s).',
