  'Payment methods' => 'Zahlungsmethoden',
  '\\nEnabled and shown on the donation checkout:%s.\\n' => 'Aktiviert und beim Spenden-Checkout angezeigt:%s.',
  '\\nCertificates after payment\\n' => 'Zertifikate nach Zahlungseingang',
  '\\nFlux Certificates makes the certificates of paid donation lines.\\n' => 'Flux Certificates erstellt die Zertifikate bezahlter Spendenlinien.',
  '\\nFlux Certificates has no active template.\\n' => 'Flux-Zertifikate haben keine aktive Vorlage.',
  '\\nProduct XML\\n' => 'Produkt-XML',
