  'Donate' => 'Spenden',
  '\\nYour bank transfer donations. If you have made the payment, upload your receipt; your certificate is sent once it is confirmed.\\n' => 'Ihre Banküberweisungsspenden. Wenn Sie die Zahlung getätigt haben, laden Sie Ihre Quittung hoch; Ihr Zertifikat wird versendet, sobald es bestätigt ist.',
  '\\nDonation #%s\\n' => 'Spende #%s',
  'Awaiting payment' => 'Warten auf Zahlung',
